import xml.etree.ElementTree as ET


_KINDS = {"tiles", "features", "coverage"}
_PROFILES = {"plain", "harmonized"}


def generate_manifest(config):
    if type(config) is not dict:
        raise TypeError("config must be a dictionary")
    if set(config) != {"name", "sources"}:
        raise ValueError("invalid config keys")
    if type(config["name"]) is not str or type(config["sources"]) is not list:
        raise TypeError("invalid config value type")
    if not config["name"]:
        raise ValueError("name cannot be empty")

    prepared = []
    names = set()
    required = {"name", "kind", "locator", "profile", "fields"}
    for source in config["sources"]:
        if type(source) is not dict:
            raise TypeError("source must be a dictionary")
        if set(source) != required:
            raise ValueError("invalid source keys")
        if any(type(source[key]) is not str for key in ("name", "kind", "locator", "profile")):
            raise TypeError("source scalars must be strings")
        if type(source["fields"]) is not dict:
            raise TypeError("fields must be a dictionary")
        name = source["name"]
        locator = source["locator"].strip().rstrip("/")
        if not name or not locator or source["kind"] not in _KINDS or source["profile"] not in _PROFILES:
            raise ValueError("invalid source value")
        if name in names:
            raise ValueError("duplicate source name")
        names.add(name)
        fields = []
        for key, value in source["fields"].items():
            if type(key) is not str or type(value) is not str:
                raise TypeError("field keys and values must be strings")
            if not key:
                raise ValueError("field key cannot be empty")
            fields.append((key, value))
        prepared.append((name, source["kind"], locator, source["profile"], fields))

    root = ET.Element("manifest", {"name": config["name"]})
    for name, kind, locator, profile, fields in sorted(prepared, key=lambda item: item[0], reverse=True):
        node = ET.SubElement(root, "source", {"name": name, "kind": kind, "profile": profile})
        ET.SubElement(node, "locator").text = locator
        for key, value in sorted(fields):
            ET.SubElement(node, "field", {"key": key}).text = value
    return ET.tostring(root, encoding="unicode", short_empty_elements=True)


def validate_manifest(xml_text):
    if type(xml_text) is not str:
        return False
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError:
        return False
    if root.tag != "manifest" or set(root.attrib) != {"name"} or not root.attrib["name"] or root.text not in (None, ""):
        return False
    source_names = []
    for source in root:
        if source.tag != "source" or set(source.attrib) != {"name", "kind", "profile"}:
            return False
        name = source.attrib["name"]
        if not name or source.attrib["kind"] not in _KINDS or source.attrib["profile"] not in _PROFILES:
            return False
        children = list(source)
        if not children or children[0].tag != "locator" or children[0].attrib:
            return False
        locator = children[0].text or ""
        if not locator or locator != locator.strip().rstrip("/") or children[0].tail not in (None, ""):
            return False
        keys = []
        for field in children[1:]:
            if field.tag != "field" or set(field.attrib) != {"key"} or list(field):
                return False
            if not field.attrib["key"] or field.tail not in (None, ""):
                return False
            keys.append(field.attrib["key"])
        if keys != sorted(keys) or len(keys) != len(set(keys)):
            return False
        source_names.append(name)
    return source_names == sorted(source_names) and len(source_names) == len(set(source_names))

